def detail(path,width,body):
    t=Table([[image_file(path,width),p(body)]],colWidths=[width+18,CW-width-18])
    t.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'MIDDLE'),('LEFTPADDING',(0,0),(-1,-1),0),('RIGHTPADDING',(0,0),(-1,-1),8)]))
    return t
def page(story,name,sub):
    if story: story.append(PageBreak())
    story.extend(title(0,name,sub))

